Here's a minimal API endpoint handling multiple image files + a description field with a 50 MB limit:

```csharp
using Microsoft.AspNetCore.Http.Features;

var builder = WebApplication.CreateBuilder(args);

// Configure max request body size
builder.WebHost.ConfigureKestrel(options =>
{
    options.Limits.MaxRequestBodySize = 50 * 1024 * 1024; // 50 MB
});

var app = builder.Build();

app.MapPost("/upload", async (HttpRequest request) =>
{
    // Ensure it's a multipart form request
    if (!request.HasFormContentType)
        return Results.BadRequest("Expected a multipart/form-data request.");

    var form = await request.ReadFormAsync();

    var description = form["description"].ToString();
    var files = form.Files.GetFiles("images");

    if (files.Count == 0)
        return Results.BadRequest("No image files provided.");

    var uploadDir = Path.Combine(Directory.GetCurrentDirectory(), "uploads");
    Directory.CreateDirectory(uploadDir);

    var saved = new List<string>();

    foreach (var file in files)
    {
        // Basic content-type validation
        if (!file.ContentType.StartsWith("image/"))
            return Results.BadRequest($"File '{file.FileName}' is not an image.");

        var safeName = $"{Guid.NewGuid()}{Path.GetExtension(file.FileName)}";
        var path = Path.Combine(uploadDir, safeName);

        await using var stream = File.Create(path);
        await file.CopyToAsync(stream);

        saved.Add(safeName);
    }

    return Results.Ok(new
    {
        Description = description,
        FileCount = saved.Count,
        FileNames = saved
    });
})
.DisableAntiforgery() // required for minimal APIs accepting form data without a token
.WithName("UploadImages");

app.Run();
```

**Key points:**

- **Size limit** — set via `MaxRequestBodySize` on Kestrel. For IIS/reverse proxy you'd also configure there.
- **`form.Files.GetFiles("images")`** — matches the `name` attribute of the file inputs (`<input type="file" name="images" multiple />`).
- **`form["description"]`** — reads the text field from the same form.
- **`.DisableAntiforgery()`** — needed in .NET 8+ minimal APIs that accept `multipart/form-data` without an antiforgery token (e.g., from an API client).

A matching `curl` test:

```bash
curl -X POST http://localhost:5000/upload \
  -F "description=My vacation photos" \
  -F "images=@photo1.jpg" \
  -F "images=@photo2.png"
```
